}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

legend {
  font-weight: 600;
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
  display: block;
}

.help-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.options-grid {
  display: grid;
  gap: 0.75rem;
}

.option-item {
  display: flex;
  align-items: center;
  padding: 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s;
}

.option-item:hover {
  background-color: #f1f5f9;
}

.option-item input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
  margin-right: 0.75rem;
  cursor: pointer;
  accent-color: var(--primary-color);
}

.option-item input:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.submit-btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  width: 100%;
  transition: background-color 0.2s;
}

.submit-btn:hover {
  background-color: #1d4ed8;
}

.submit-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.result {
  margin-top: 1.5rem;
  padding: 1rem;
  border-radius: 8px;
  background-color: #ecfdf5;
  color: #065f46;
  text-align: center;
  font-weight: 600;
}
